function adaptPromptBasedOnResponse(basePrompt, responseQuality) {
  if (responseQuality.engagement < 0.5) {
    return `${basePrompt}\n\n请尝试更活泼、更有趣的回复方式。`;
  } else if (responseQuality.emotionalMatch < 0.6) {
